SELECT CASE WHEN budget >= 4121000 THEN 'high' WHEN budget >= 1350000 THEN 'mid' ELSE 'low' END AS budget_bucket, location, COUNT(CASE WHEN location = 'London' THEN 1 END) AS london_count FROM departments WHERE location NOT IN ('Bangkok', 'Chiang Mai') AND (dept_name <> 'Sales' OR budget > 2208000) GROUP BY CASE WHEN budget >= 4121000 THEN 'high' WHEN budget >= 1350000 THEN 'mid' ELSE 'low' END, location HAVING london_count < 1
